        ]
    else:  # odd row
        offsets = [
            (1, 0),   # E
            (1, -1),  # NE
            (0, -1),  # NW
            (-1, 0),  # W
            (0, 1),   # SW
            (1, 1),   # SE
        ]

    neighbors = []
    for dx, dy in offsets:
        nx, ny = x + dx, y + dy
        if 0 <= nx < width and 0 <= ny < height:
