def is_mountain(x, y):
    return (x, y) in map_data and 'MOUNTAIN' in map_data[(x, y)]['terrain']

def has_jungle(x, y):
    return (x, y) in map_data and map_data[(x, y)].get('feature') == 'FEATURE_JUNGLE'

def has_forest(x, y):
    return (x, y) in map_data and map_data[(x, y)].get('feature') in ('FEATURE_FOREST', 'FEATURE_JUNGLE')

def has_geothermal(x, y):
    return (x, y) in map_data and map_data[(x, y)].get('feature') == 'FEATURE_GEOTHERMAL_FISSURE'

def is_adjacent_to_river(x, y):
    if (x, y) in river_data:
        r = river_data[(x, y)]
        return r.get('NE') or r.get('W') or r.get('NW')
    return False

